/*** Se usa query para buscar los datos ******/

SELECT STATUS,STATUS2,STATUS3,AGENTE,FECHA_VENCIMIENTO,TIPO_TRANSACCION,CODIGO_CLIENTE,D_CODIGO_CLIENTE,CARACTER_ASIENTO,DOCUMENTO,FECHA_FACTURA,P_IMPORTE,IMPORTE_COBRADO,BANCO,RESERVADOA01,RESERVADOA02,D_AGENTE,CODIGO_CUENTA,D_CODIGO_CUENTA,DOMICILIACION_MANUAL,DIVISA_ORIGEN,P_IMPORTE_DIVISA,P_IMPORTE_DIVISA_NUM,FECHA_VALOR,TIPO_REMESA,D_TIPO_REMESA,NUMERO_REMESA,FECHA_REMESA,TIPO_REMESA_FINANCIACION,D_TIPO_REMESA_FINANCIACION,FECHA_REMESA_FINANCIACION,NUMERO_REMESA_FINANCIACION,D_BANCO,BANCO_REMESA_FINANCIACION,D_BANCO_REMESA_FINANCIACION,NUM_CHEQUE,ESTADO,EMPRESA,FECHA_ASIENTO_TD,FECHA_VENCIMIENTO_ORIGINAL,DIARIO,NUMERO_ASIENTO_BORRADOR,NUMERO_LINEA_BORRADOR,CONCEPTO,IMPORTE,IMPORTE_ENDOSADO,IMPORTE_SUSTITUIDO_DIVISA,IMPORTE_SUSTITUIDO,IMPORTE_DIVISA,IMPORTE_COBRADO_DIVISA,FECHA_VALOR_DIVISA,STATUS_REMESADO,STATUS_IMPRESION,STATUS_ACEPTADO,STATUS_IMPAGADO,STATUS_RETENIDO,STATUS_FINANCIADO,DOCUMENTO_VIVO,IMPORTE_DIV_NO_ASEGURADO,VALOR_CAMBIO,VALOR_CAMBIO_NO_ASEG,IMPORTE_DIVISA_ASEGURADO,IMPORTE_PDTE_DIVISA,IMPORTE_PDTE 
FROM (SELECT HC.* ,DECODE(hc.agente,NULL,NULL,(SELECT lvag.nombre FROM agentes lvag WHERE lvag.codigo = hc.agente AND lvag.empresa = hc.empresa)) D_AGENTE,DECODE(hc.banco_asegurador,NULL,NULL,(SELECT lvba.nombre FROM bancos lvba WHERE lvba.codigo_rapido = hc.banco_asegurador AND lvba.empresa = hc.empresa)) D_BANCO_ASEGURADOR,(SELECT c.nombre FROM clientes c WHERE c.codigo_rapido = hc.codigo_cliente AND c.codigo_empresa = hc.empresa) D_CODIGO_CLIENTE,(SELECT c.nombre FROM cuentas c WHERE c.empresa = hc.empresa AND c.estado = hc.estado AND c.codigo = hc.codigo_cuenta) D_CODIGO_CUENTA,pk_fecha_asiento.get_fechas(hc.empresa,hc.tipo_transaccion,hc.fecha_vencimiento,hc.fecha_factura,hc.documento) FECHA_ASIENTO_TD,f_cobros_cambios(pkpantallas.get_variable_env_varchar2('CAMBIO_ACTUAL'), pkpantallas.get_variable_env_varchar2('CAMBIO_ASEGURADO'), pkpantallas.get_variable_env_varchar2('DIVISA_PRESENTACION'), pkpantallas.get_variable_env_varchar2('CODIGO_DIVISA_PRESENTACION'), pkpantallas.get_variable_env_number('CAMBIO_DIVISA_PRESEN'), pkpantallas.get_variable_env_date('FECHA_VALOR'), pkpantallas.get_variable_env_varchar2('DIVISA_EMPRESA'), pkpantallas.get_variable_env_number('DECIMALES_EMPRESA'), divisa_origen, importe_divisa, importe_cobrado_divisa,valor_cambio, documento_vivo, importe_div_no_asegurado, valor_cambio_no_aseg, importe_divisa_asegurado, importe_pdte_divisa, importe, importe_endosado, importe_sustituido, importe_cobrado, importe_sustituido_divisa) P_IMPORTE,TO_CHAR(v_importe_divisa, pkmascaras.importes(15, 4, divisa_origen)) P_IMPORTE_DIVISA,v_importe_divisa P_IMPORTE_DIVISA_NUM,NULL RESERVADOA01,NULL RESERVADOA02,DECODE(hc.status_retenido,'S', 'R', DECODE(NVL(hc.status_impagado, 'N'), 'N', ' ', DECODE(hc.status_impagado, 'S', 'I', hc.status_impagado))) STATUS,DECODE(hc.numero_remesa_financiacion, NULL, NULL,(SELECT fn.codigo_banco FROM financiaciones fn WHERE hc.empresa = fn.empresa AND hc.numero_remesa_financiacion = fn.numero AND hc.fecha_remesa_financiacion = fn.fecha_remesa)) BANCO_REMESA_FINANCIACION,DECODE(hc.banco,NULL,NULL,(SELECT lvba.nombre FROM bancos lvba WHERE lvba.codigo_rapido = hc.banco AND lvba.empresa = hc.empresa)) D_BANCO,DECODE(hc.numero_remesa_financiacion, NULL, NULL,(SELECT b.nombre FROM bancos b WHERE hc.empresa = b.empresa AND codigo_rapido =(SELECT fn.codigo_banco FROM financiaciones fn WHERE hc.empresa = fn.empresa AND hc.numero_remesa_financiacion = fn.numero AND hc.fecha_remesa_financiacion = fn.fecha_remesa))) D_BANCO_REMESA_FINANCIACION,DECODE(hc.numero_remesa, NULL, NULL, (SELECT tr.descripcion FROM tipos_remesa tr WHERE hc.empresa = tr.empresa AND codigo = (SELECT r.tipo_remesa FROM remesas r WHERE hc.empresa=r.empresa AND hc.numero_remesa = r.numero AND hc.fecha_remesa=r.fecha_remesa))) D_TIPO_REMESA,DECODE(hc.numero_remesa_financiacion, NULL, NULL, (SELECT trf.descripcion FROM tipos_remesa_financiacion trf WHERE hc.empresa = trf.empresa AND codigo = (SELECT fn.tipo_remesa FROM financiaciones fn WHERE hc.empresa = fn.empresa AND hc.numero_remesa_financiacion = fn.numero AND hc.fecha_remesa_financiacion = fn.fecha_remesa))) D_TIPO_REMESA_FINANCIACION,CASE
WHEN hc.status_remesado = 'S' THEN 'RE'
WHEN hc.status_remesado = 'N' AND (SELECT tt.remesable FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'S' AND (hc.status_aceptado = 'S' OR (SELECT tt.aceptar FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'N') AND (hc.status_impresion = 'S' OR (SELECT tt.imprimir FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'N') THEN 'PR'
WHEN hc.status_aceptado = 'S' AND (SELECT tt.aceptar FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'S' THEN 'AC'
WHEN hc.status_impresion = 'N' AND (SELECT tt.imprimir FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'S' THEN 'NE'
WHEN hc.status_aceptado = 'N' AND (SELECT tt.aceptar FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'S' AND ((hc.status_impresion = 'S' AND (SELECT tt.imprimir FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'S') OR (SELECT tt.imprimir FROM tipos_transacciones tt WHERE tt.codigo = hc.tipo_transaccion) = 'N') THEN 'EN'
END STATUS2,DECODE(NVL(hc.status_financiado, 'N'), 'S', 'F', DECODE(NVL(hc.status_remesado, 'N'), 'N', 'NF')) STATUS3,DECODE(hc.numero_remesa,NULL, NULL,(SELECT r.tipo_remesa FROM remesas r WHERE hc.empresa = r.empresa AND hc.numero_remesa = r.numero AND hc.fecha_remesa = r.fecha_remesa)) TIPO_REMESA,DECODE(hc.numero_remesa_financiacion, NULL, NULL, (SELECT fn.tipo_remesa FROM financiaciones fn WHERE hc.empresa = fn.empresa AND hc.numero_remesa_financiacion = fn.numero AND hc.fecha_remesa_financiacion = fn.fecha_remesa)) TIPO_REMESA_FINANCIACION 

FROM V_HISTORICO_COBROS HC) HC 
WHERE empresa='004' AND situacion_apunte = 'D' AND NVL(status_remesado, 'N') = 'N' AND documento_vivo = 'S' AND exists ( select 1 from centros_grupo_ccont cgc where cgc.empresa = '004' and cgc.codigo_centro = hc.caracter_asiento and cgc.codigo_grupo = '0401') AND (status_retenido = 'N' OR status_retenido IS NULL OR status_retenido = 'S') 
AND NVL(STATUS_IMPAGADO,'N') IN ( 'N','S','D','P','A','F') AND codigo_cliente >= '011567' AND codigo_cliente <= '011567'  
order by FECHA_VENCIMIENTO,TIPO_TRANSACCION,CODIGO_CLIENTE



-- Campos requeridos: Fecha factura, Fecha vencimiento, Numero Factura, Saldo, Importe, código Cliente
-- query para obtener los datos requeridos
EMPRESA, CODIGO_CLIENTE, FECHA_FACTURA, FECHA_VENCIMIENTO,DOCUMENTO, IMPORTE, IMPORTE_COBRADO, IMPORTE_PDTE

select EMPRESA, CODIGO_CLIENTE, FECHA_FACTURA, FECHA_VENCIMIENTO,DOCUMENTO, IMPORTE, IMPORTE_COBRADO, IMPORTE_PDTE
FROM V_HISTORICO_COBROS
WHERE empresa='004' AND situacion_apunte = 'D' AND NVL(status_remesado, 'N') = 'N' AND documento_vivo = 'S'
AND NVL(STATUS_IMPAGADO,'N') IN ( 'N','S','D','P','A','F')
GROUP BY EMPRESA
order by FECHA_VENCIMIENTO,TIPO_TRANSACCION,CODIGO_CLIENTE

select EMPRESA, count(*) cnt 
FROM V_HISTORICO_COBROS
WHERE empresa='004' AND situacion_apunte = 'D' AND NVL(status_remesado, 'N') = 'N' AND documento_vivo = 'S'
AND NVL(STATUS_IMPAGADO,'N') IN ( 'N','S','D','P','A','F')
GROUP BY EMPRESA